import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.BM5YPQmL.js";const k=JSON.parse('{"title":"درس الموانئ والخدمات اللوجستية","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/tutorials/ports-logistics.md","filePath":"ar/guide/tutorials/ports-logistics.md"}'),n={name:"ar/guide/tutorials/ports-logistics.md"};function l(o,s,r,h,p,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="درس-الموانئ-والخدمات-اللوجستية" tabindex="-1">درس الموانئ والخدمات اللوجستية <a class="header-anchor" href="#درس-الموانئ-والخدمات-اللوجستية" aria-label="Permalink to &quot;درس الموانئ والخدمات اللوجستية&quot;">​</a></h1><p>في هذا الدرس تصنع فيديو موضوعه: رحلة حاوية من السفينة إلى الشاحنة في ميناء خيالي. ستستخدم الحزمة <code>ports-logistics</code> وثيمها <code>harbor</code>، ويستغرق العمل نحو عشر دقائق قبل التسجيل.</p><h2 id="_1-أنشئ-الحلقة" tabindex="-1">1. أنشئ الحلقة <a class="header-anchor" href="#_1-أنشئ-الحلقة" aria-label="Permalink to &quot;1. أنشئ الحلقة&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container-journey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ports-logistics</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container-journey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ar</span></span></code></pre></div><p>استخدم <code>--lang en</code> لنسخة إنجليزية. وتضم الحزمة أيضاً القالبين <code>terminal-in-numbers</code> و<code>new-route</code>. يعرض <a href="./../../reference/packs.html#ports-logistics">فهرس الحزم</a> كل القوالب وحقولها.</p><h2 id="_2-أدخل-بياناتك" tabindex="-1">2. أدخل بياناتك <a class="header-anchor" href="#_2-أدخل-بياناتك" aria-label="Permalink to &quot;2. أدخل بياناتك&quot;">​</a></h2><p>افتح الحلقة بالأمر <code>reelforge edit container-journey</code> واستبدل الأسماء والأرقام والكلمة المفتاحية الافتراضية ببياناتك، أو ابدأ من لوحة التحكم (<strong>+ New episode</strong> ثم <strong>Start from template</strong>)، فيطلب النموذج كل حقل على حدة. التزم بحدود الطول الظاهرة لكل حقل.</p><p><strong>الجمهور والنبرة.</strong> المستوردون والمصدّرون ووكلاء الشحن والسائقون وموظفو الموانئ. كن دقيقاً وعملياً، فالأرقام هنا مهمة.</p><ul><li>اعرض المراحل بمكوّن <code>flow</code> مع مؤشر متحرك (token)، مرحلة لكل خطوة منطوقة.</li><li>أبقِ المصطلحات الإنجليزية داخل الجملة العربية (<code>الـ container</code> و<code>الـ customs</code>).</li><li>ضع وسم «مثال» على الأزمنة والكميات ما لم يقدّم العميل أرقاماً حقيقية.</li></ul><h2 id="_3-راجع-المحتوى" tabindex="-1">3. راجع المحتوى <a class="header-anchor" href="#_3-راجع-المحتوى" aria-label="Permalink to &quot;3. راجع المحتوى&quot;">​</a></h2><ul><li>لا موانئ ولا شركات شحن ولا سفن ولا مشغّلي محطات حقيقيين.</li><li>قواعد الجمارك تختلف من بلد لآخر: قدّمها كأمثلة وأحِل المشاهدين إلى الجهة المحلية المختصة.</li><li>لا تفاصيل أمنية مثل إجراءات البوابات أو التفتيش.</li></ul><h2 id="_4-تحقق-وسجّل-وصدّر" tabindex="-1">4. تحقق وسجّل وصدّر <a class="header-anchor" href="#_4-تحقق-وسجّل-وصدّر" aria-label="Permalink to &quot;4. تحقق وسجّل وصدّر&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container-journey</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container-journey</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # after you save voice.wav in the episode folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container-journey</span></span></code></pre></div><p>يوجد مثال مكتمل في <code>packs/ports-logistics/examples/azur-container-ar</code>؛ صدّره مع الخيار <code>--silent</code> للمقارنة.</p>`,14)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
